<script lang="ts">
 import {onMount} from 'svelte';
 import {Client,can} from './client.ts';
 type RunStatus={identity:{scopes:string[]};quantum:number;run:{id:string;epoch:string;state:string;granted:number;requested:number;speed:number}};
 type Route={code:string;origin:string;destination:string;journey_seconds:number};
 type Vehicle={code:string;location:string;capacity:number;transfer_id:string|null};
 type Transfer={id:string;route:string;sku:string;quantity:number;status:string;custody:string;vehicle:string|null;origin:string;destination:string;planned_eta:number|null;departed_at:number|null;arrived_at:number|null;received_at:number|null;correlation_id:string};
 type Command={id:string;command:{action:string;reference?:string};status:string;reason:string|null;due_at:number;attempts:number};
 type Snapshot={configuration:{routes:Route[]};vehicles:Vehicle[];transfers:Transfer[];commands:Command[];movements:{action:string;simulation_time:number;transfer_id:string;quantity:number;custody:string}[]};
 let {client,status}: {client:Client;status:RunStatus}=$props();
 let snapshot:Snapshot|undefined=$state();let error=$state('');let message=$state('');let busy=$state(false);let route=$state('');let sku=$state('PRODUCT');let quantity=$state(1);let correlation=$state(crypto.randomUUID());let assignments:Record<string,string>=$state({});let retry:ReturnType<Client['transport']>|undefined=$state();
 const writable=$derived(can(status.identity,'jobs:write')&&['running','held'].includes(status.run.state));
 const stages=['requested','assigned','loaded','in_transit','arrived','unloaded','received'];
 const stageLabels=['Requested','Assigned','Loaded','Departed','Arrived','Unloaded','Received'];
 function stageIndex(tr:Transfer){return Math.max(0,stages.indexOf(tr.status))}
 function progress(tr:Transfer){if(tr.departed_at===null||tr.planned_eta===null)return 0;return Math.round(Math.max(0,Math.min(100,100*(status.run.granted-tr.departed_at)/(tr.planned_eta-tr.departed_at))))}
 async function refresh(){try{snapshot=await client.request<Snapshot>('/api/transport');if(!route&&snapshot.configuration.routes.length)route=snapshot.configuration.routes[0].code}catch(e){error=e instanceof Error?e.message:String(e)}}
 function pending(id:string){return snapshot?.commands.some(c=>c.status==='pending'&&(c.id===id||c.command.reference===id))??false}
 async function send(action:string,fields:Record<string,unknown>){if(busy||retry)return;busy=true;error='';message='';try{
  const current=await client.request<RunStatus>('/api/status');if(current.run.id!==status.run.id||current.run.epoch!==status.run.epoch)throw new Error('The run changed. Refresh before issuing another command.');
  retry=client.transport({run_id:current.run.id,epoch:current.run.epoch,due_at:Math.max(current.run.granted,current.run.requested)+2*current.quantum+current.run.speed,action,...fields});await deliver()
 }catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
 async function deliver(){if(!retry)return;try{const saved=await retry.send();retry=undefined;message=`Command accepted: ${saved.id}`;await refresh()}catch(e){error=e instanceof Error?e.message:String(e)}}
 async function retryCommand(){busy=true;error='';await deliver();busy=false}
 function request(event:SubmitEvent){event.preventDefault();void send('request',{route,sku,quantity,correlation_id:correlation});correlation=crypto.randomUUID()}
 onMount(()=>{void refresh();const timer=setInterval(refresh,750);return()=>clearInterval(timer)});
</script>
{#if error}<div class="notice" role="alert">{error}</div>{/if}
{#if retry}<section><h2>Command awaiting confirmation</h2><p>The saved command retains its original fields and idempotency key.</p><div class="actions"><button onclick={retryCommand} disabled={busy}>Retry same transport command</button><button onclick={()=>{retry=undefined;error=''}}>New transport command</button></div></section>{/if}
{#if message}<p role="status" class="identifier">{message}</p>{/if}
{#if snapshot}
 <div class="dispatch-workspace">
 <section data-transfers class="transfer-board"><div class="section-title"><div><p class="section-number">01</p><h2>Transport queue</h2></div><span>{snapshot.transfers.length} transfers</span></div><p>ETA is planned simulation time. Arrival confirms the journey; receipt confirms the destination accepted the goods.</p><div class="transfer-list">{#each snapshot.transfers as tr}<article class="transfer-card"><div class="transfer-summary"><div><span class="identifier">{tr.id}</span><h3>{tr.origin} <span aria-hidden="true">→</span> {tr.destination}</h3><p>{tr.quantity} {tr.sku} · {tr.route}</p></div><div class="transfer-state"><span>{tr.status}</span><strong>{tr.vehicle??'Unassigned'}</strong><small>Custody: {tr.custody}</small></div></div><ol class="transfer-track" aria-label={`Transfer status: ${tr.status}`}>{#each stageLabels as label,index}<li class:complete={index<stageIndex(tr)} class:current={index===stageIndex(tr)}><span>{index+1}</span>{label}</li>{/each}</ol><div class="transfer-footer"><div class="timing"><span>Planned ETA <strong>{tr.planned_eta??'—'} s</strong></span><span>Arrived <strong>{tr.arrived_at??'—'} s</strong></span>{#if tr.departed_at!==null}<span>Progress <strong>{progress(tr)}%</strong></span>{/if}</div>{#if writable&&!pending(tr.id)}<div class="actions">{#if tr.status==='requested'}<select aria-label="Assign vehicle" value={assignments[tr.id]??''} onchange={e=>{assignments[tr.id]=e.currentTarget.value}}><option value="">Select vehicle</option>{#each snapshot.vehicles.filter(v=>!v.transfer_id&&v.location===tr.origin&&v.capacity>=tr.quantity) as v}<option value={v.code}>{v.code} ({v.capacity} items)</option>{/each}</select><button class="primary" onclick={()=>send('assign',{reference:tr.id,vehicle:assignments[tr.id]})} disabled={busy||!!retry||!assignments[tr.id]}>Assign</button>{:else if tr.status==='assigned'}<button class="primary" onclick={()=>send('load',{reference:tr.id})} disabled={busy||!!retry}>Load</button>{:else if tr.status==='loaded'}<button class="primary" onclick={()=>send('depart',{reference:tr.id})} disabled={busy||!!retry}>Depart</button>{:else if tr.status==='in_transit'&&tr.planned_eta!==null&&status.run.granted>=tr.planned_eta}<button class="primary" onclick={()=>send('arrive',{reference:tr.id})} disabled={busy||!!retry}>Confirm arrival</button>{:else if tr.status==='arrived'}<button class="primary" onclick={()=>send('unload',{reference:tr.id})} disabled={busy||!!retry}>Unload</button>{:else if tr.status==='unloaded'}<button class="primary" onclick={()=>send('receive',{reference:tr.id})} disabled={busy||!!retry}>Confirm receipt</button>{/if}</div>{:else if pending(tr.id)}<span class="pending-state">Command pending</span>{/if}</div></article>{:else}<div class="empty-state"><h3>No transport requested</h3><p>New requests will appear here with their full custody lifecycle.</p></div>{/each}</div></section>
 <aside class="dispatch-rail">{#if writable}<section><div class="section-title"><div><p class="section-number">02</p><h2>Request transport</h2></div></div><form onsubmit={request}><label>Route<select bind:value={route} required>{#each snapshot.configuration.routes as r}<option value={r.code}>{r.origin} → {r.destination}</option>{/each}</select></label><label>SKU<input bind:value={sku} pattern={'[A-Z0-9][A-Z0-9_-]{0,31}'} maxlength="32" required /></label><label>Load quantity<input type="number" min="1" max="10000" step="1" bind:value={quantity} required /></label><label>Correlation ID<input bind:value={correlation} required /></label><button class="primary full-width" disabled={busy||!!retry}>Request transport</button></form></section>{/if}<section data-fleet><div class="section-title"><div><p class="section-number">03</p><h2>Fleet availability</h2></div><span>{snapshot.vehicles.length}</span></div><ul class="fleet-list">{#each snapshot.vehicles as vehicle}<li><div><strong>{vehicle.code}</strong><span>{vehicle.location}</span></div><div><strong>{vehicle.capacity}</strong><span>{vehicle.transfer_id?'Reserved':'Available'}</span></div></li>{/each}</ul><h3 class="route-title">Configured routes</h3><ul class="route-list">{#each snapshot.configuration.routes as r}<li><strong>{r.code}</strong><span>{r.origin} → {r.destination}</span><small>{r.journey_seconds} s</small></li>{/each}</ul></section></aside></div>
 <div class="operations-secondary"><section><div class="section-title"><div><p class="section-number">04A</p><h2>Transport commands</h2></div></div><div class="table-wrap"><table><thead><tr><th>Command</th><th>Due (s)</th><th>Action</th><th>Outcome</th><th>Reason</th></tr></thead><tbody>{#each snapshot.commands as command}<tr><td class="identifier">{command.id}</td><td>{command.due_at}</td><td>{command.command.action}</td><td>{command.status}</td><td>{command.reason??'—'}</td></tr>{:else}<tr><td colspan="5">No transport commands.</td></tr>{/each}</tbody></table></div></section><section><div class="section-title"><div><p class="section-number">04B</p><h2>Custody history</h2></div></div><div class="table-wrap"><table><thead><tr><th>Time (s)</th><th>Transfer</th><th>Action</th><th>Quantity</th><th>Custody</th></tr></thead><tbody>{#each snapshot.movements as movement}<tr><td>{movement.simulation_time}</td><td class="identifier">{movement.transfer_id}</td><td>{movement.action}</td><td>{movement.quantity}</td><td>{movement.custody}</td></tr>{:else}<tr><td colspan="5">No custody movements.</td></tr>{/each}</tbody></table></div></section></div>
{/if}
